import os, sys, glob
from defusedxml import minidom

# Locate unpacked dir
candidates = ["unpacked", "unpacked/word/document.xml"]
base = "unpacked"
doc_path = os.path.join(base, "word", "document.xml")
print("document.xml exists:", os.path.exists(doc_path))

dom = minidom.parse(doc_path)
W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"

def local(tag):
    return tag.split("}")[-1] if "}" in tag else tag

paras = dom.getElementsByTagNameNS(W, "p")
print("total paragraphs:", len(paras))
for i, p in enumerate(paras):
    pPr = None
    for child in p.childNodes:
        if child.nodeType == child.ELEMENT_NODE and local(child.tagName) == "pPr":
            pPr = child
            break
    style = ""
    if pPr is not None:
        for child in pPr.childNodes:
            if child.nodeType == child.ELEMENT_NODE and local(child.tagName) == "pStyle":
                style = child.getAttributeNS(W, "val")
    # gather text
    texts = []
    for r in p.getElementsByTagNameNS(W, "r"):
        for t in r.childNodes:
            if t.nodeType == t.ELEMENT_NODE and local(t.tagName) == "t":
                texts.append(t.firstChild.nodeValue if t.firstChild else "")
            elif t.nodeType == t.ELEMENT_NODE and local(t.tagName) == "delText":
                texts.append("[del:" + (t.firstChild.nodeValue if t.firstChild else "") + "]")
    content = "".join(texts)
    if style or content.strip():
        print(f"[{i}] style='{style}' | {content[:120]}")

import os, sys, glob

def main():
    base = "unpacked"
    for root, dirs, files in os.walk(base):
        level = root.replace(base, "").count(os.sep)
        indent = " " * 2 * level
        print(f"{indent}{os.path.basename(root)}/")
        sub = " " * 2 * (level + 1)
        for f in files:
            print(f"{sub}{f}")

if __name__ == "__main__":
    main()
